script:
(function () {
  'use strict';
  // 2026 self-employment tax, following Schedule SE (Form 1040) Part I and Form 8959 Part II:
  //   line 3  = net farm profit + net business profit (Schedule F + Schedule C)
  //   line 4a = line 3 x 92.35% when positive; under $400 -> no SE tax (line 4c = 0)
  //   line 5b = church employee income x 92.35% (0 if under $100)
  //   line 6  = net earnings from self-employment = 4c + 5b
  //   line 9  = Social Security wage base - W-2 Social Security wages and tips (not below 0)
  //   line 10 = 12.4% x min(line 6, line 9); line 11 = 2.9% x line 6; SE tax = 10 + 11
  //   line 13 = deductible half of SE tax (adjustment to income on Schedule 1)
  //   Additional Medicare Tax (Form 8959 line 13) = 0.9% x (line 6 - max(0, threshold - Medicare
  //     wages)); it is not part of SE tax and is not included in the deductible half.
  // Not modeled: farm/nonfarm optional methods, Form 4137/8919 wages, Conservation Reserve payments.
  // Verified (Node, scratchpad tests/w3b2e): $50,000 profit -> net earnings $46,175.00, SE tax
  //   $7,064.78 (same as income-tax-calculator), deduction $3,532.39. $200,000 profit -> SS capped at
  //   $184,500 x 12.4% = $22,878.00, Medicare $5,356.30, total $28,234.30, no Additional Medicare.
  //   $300,000 profit, single -> SE tax $30,912.45, Additional Medicare $693.45 (0.9% x $77,050).
  //   $100,000 profit + $150,000 W-2 wages -> SS on $34,500 only = $4,278.00, Medicare $2,678.15,
  //   Additional Medicare 0.9% x ($92,350 - $50,000) = $381.15. $433 profit -> $399.88 net, no tax.
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Social Security wage base $184,500: SSA 2026 COLA fact sheet / Form 1040-ES (2026) - same
  //   constant as take-home-paycheck-calculator and income-tax-calculator.
  // 92.35% factor, 12.4% + 2.9% rates, $400 and $100 floors: IRC 1401, 1402; Schedule SE.
  // Additional Medicare thresholds ($250,000 MFJ, $125,000 MFS, $200,000 others) are statutory and
  //   not indexed: IRC 1401(b)(2); IRS Form 8959 instructions.
  var TAX_YEAR = 2026;
  var SS_WAGE_BASE = 184500, SE_FACTOR = 0.9235, SE_SS = 0.124, SE_MED = 0.029;
  var SE_MIN = 400, CHURCH_MIN = 100;
  var ADDL_MED_RATE = 0.009, ADDL_MED = { mfj: 250000, mfs: 125000, other: 200000 };
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 1, maximumFractionDigits: 1 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }

  function read(id, blank) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blank;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function calculate(o) {
    var line3 = o.business + o.farm;
    var line4a = line3 > 0 ? line3 * SE_FACTOR : line3;
    var line4c = line4a < SE_MIN ? 0 : line4a;
    var line5b = Math.max(0, o.church) * SE_FACTOR;
    if (line5b < CHURCH_MIN) line5b = 0;
    var line6 = line4c + line5b;
    var line9 = Math.max(0, SS_WAGE_BASE - o.ssWages);
    var ssBase = Math.min(line6, line9);
    var ssTax = SE_SS * ssBase;
    var medTax = SE_MED * line6;
    var seTax = ssTax + medTax;
    var threshold = ADDL_MED[o.status] !== undefined ? ADDL_MED[o.status] : ADDL_MED.other;
    var reducedThreshold = Math.max(0, threshold - o.medWages);
    var addlBase = Math.max(0, line6 - reducedThreshold);
    var addl = ADDL_MED_RATE * addlBase;
    return {
      line3: line3, line4a: line4a, line4c: line4c, line5b: line5b, line6: line6, line9: line9,
      ssBase: ssBase, ssTax: ssTax, medTax: medTax, seTax: seTax, deduction: seTax / 2,
      threshold: threshold, reducedThreshold: reducedThreshold, addlBase: addlBase, addl: addl,
      total: seTax + addl, belowFloor: line4a > 0 && line4a < SE_MIN
    };
  }

  var OUT = ['seTax', 'seDeduction', 'seAddl', 'seTotal', 'seNetEarnings', 'seSsPart', 'seMedPart',
             'seEffective', 'seQuarterly'];

  function clear() {
    OUT.forEach(function (id) { setText(id, '–'); });
    el('seBreakdown').innerHTML = '';
    el('seNote').hidden = true;
  }

  function update() {
    var o = {
      status: el('seStatus').value,
      business: read('seBusiness', 0), farm: read('seFarm', 0),
      ssWages: read('seWages', 0), church: read('seChurch', 0)
    };
    var med = read('seMedWages', null);
    o.medWages = med === null ? o.ssWages : med;
    var err = el('seError');
    var bad = [o.business, o.farm, o.ssWages, o.church, o.medWages].some(isNaN) ||
              o.ssWages < 0 || o.church < 0 || o.medWages < 0 ||
              Math.abs(o.business) > 1e11 || Math.abs(o.farm) > 1e11 || o.ssWages > 1e11 || o.medWages > 1e11 || o.church > 1e11;
    err.hidden = !bad;
    if (bad) {
      err.textContent = 'Enter dollar amounts as numbers. Profits can be negative (a loss); wages cannot.';
      clear();
      return;
    }
    var r = calculate(o);
    setText('seTax', money.format(r.seTax));
    setText('seDeduction', money.format(r.deduction));
    setText('seAddl', money.format(r.addl));
    setText('seTotal', money.format(r.total));
    setText('seNetEarnings', money.format(r.line6));
    setText('seSsPart', money.format(r.ssTax));
    setText('seMedPart', money.format(r.medTax));
    var profit = Math.max(0, r.line3) + Math.max(0, o.church);
    setText('seEffective', profit > 0 ? pct.format(r.total / profit) : '–');
    setText('seQuarterly', money.format(r.total / 4));

    var rows = [
      ['Net profit or loss (business + farm)', money.format(r.line3)],
      ['× 92.35% = net earnings before church income', money.format(r.line4a > 0 ? r.line4a : 0)],
      ['Church employee income × 92.35%', money.format(r.line5b)],
      ['Net earnings from self-employment', money.format(r.line6)],
      [TAX_YEAR + ' Social Security wage base', money.format(SS_WAGE_BASE)],
      ['Wage base left after W-2 Social Security wages', money.format(r.line9)],
      ['Earnings taxed for Social Security', money.format(r.ssBase)],
      ['Social Security tax (12.4%)', money.format(r.ssTax)],
      ['Medicare tax (2.9% of all net earnings)', money.format(r.medTax)],
      ['Self-employment tax', money.format(r.seTax)],
      ['Deductible half of self-employment tax', money.format(r.deduction)],
      ['Additional Medicare threshold for your filing status', money.format(r.threshold)],
      ['Threshold left after W-2 Medicare wages', money.format(r.reducedThreshold)],
      ['Additional Medicare Tax (0.9% of ' + money.format(r.addlBase) + ')', money.format(r.addl)]
    ];
    el('seBreakdown').innerHTML = rows.map(function (row) {
      return '<tr><td>' + row[0] + '</td><td>' + row[1] + '</td></tr>';
    }).join('');

    var notes = [];
    if (r.belowFloor) notes.push('Your net earnings from self-employment are under ' + whole.format(SE_MIN) + ', so no self-employment tax is due on them.');
    if (r.line3 < 0) notes.push('A net loss means no self-employment tax on business or farm income this year.');
    if (o.ssWages >= SS_WAGE_BASE && r.line6 > 0) notes.push('Your W-2 wages already reach the ' + whole.format(SS_WAGE_BASE) + ' wage base, so only the 2.9% Medicare part applies to your self-employment earnings.');
    if (o.medWages > r.threshold) notes.push('Your wages are also over the Additional Medicare threshold. The 0.9% on those wages is figured separately on Form 8959 (and usually withheld by your employer), so it is not included here.');
    var note = el('seNote');
    note.hidden = notes.length === 0;
    note.textContent = notes.join(' ');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('seForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
